import React, { useEffect, useMemo } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { getProductsList } from '../actions/productActions'
import Message from '../components/Message'
import { Spinner } from 'react-bootstrap'
import Product from '../components/Product'
import { useHistory } from 'react-router-dom'
import { CREATE_PRODUCT_RESET } from '../constants'

function ProductsListPage() {

    const history = useHistory()
    const dispatch = useDispatch()

    // =========================================
    // GET SEARCH + CATEGORY FROM URL
    // =========================================

    const params = new URLSearchParams(history.location.search)

    const searchTerm =
        params.get('searchTerm') || ''

    const category =
        params.get('category') || ''


    // =========================================
    // REDUX PRODUCTS
    // =========================================

    const productsListReducer = useSelector(
        state => state.productsListReducer
    )

    const {
        loading,
        error,
        products = []
    } = productsListReducer


    // =========================================
    // LOAD PRODUCTS
    // =========================================

    useEffect(() => {

        dispatch(getProductsList())

        dispatch({
            type: CREATE_PRODUCT_RESET
        })

    }, [dispatch])


    // =========================================
    // DEBUG
    // =========================================

    useEffect(() => {

        if (products.length > 0) {

            console.log(
                'TOTAL PRODUCTS:',
                products.length
            )

            console.log(
                'PRODUCT NAMES:',
                products.map(product => ({
                    name: product.name,
                    description: product.description,
                    category: product.category
                }))
            )

        }

    }, [products])


    // =========================================
    // CATEGORY DETECTION
    // =========================================

    const getCategory = (product) => {

        const productCategory =
            product.category
                ? product.category.toLowerCase()
                : ''

        const text = `
            ${product.name || ''}
            ${product.description || ''}
            ${productCategory}
        `.toLowerCase()


        // KURTIS
        if (
            text.includes('kurti') ||
            text.includes('kurta')
        ) {
            return 'Kurtis'
        }


        // SAREES
        if (
            text.includes('saree') ||
            text.includes('sari')
        ) {
            return 'Sarees'
        }


        // LEHENGAS
        if (
            text.includes('lehenga')
        ) {
            return 'Lehengas'
        }


        // WOMEN WESTERN
        if (
            text.includes('western') ||
            text.includes('dress') ||
            text.includes('gown') ||
            text.includes('tops')
        ) {
            return 'Women Western'
        }


        // MEN
        if (
            text.includes('mens') ||
            text.includes("men's") ||
            text.includes('shirt') ||
            text.includes('t-shirt') ||
            text.includes('mens-shirts')
        ) {
            return 'Men'
        }


        // KIDS & TOYS
        if (
            text.includes('kids') ||
            text.includes('toy')
        ) {
            return 'Kids & Toys'
        }


        // HOME & KITCHEN
        if (
            text.includes('home') ||
            text.includes('kitchen') ||
            text.includes('furniture')
        ) {
            return 'Home & Kitchen'
        }


        // BEAUTY
        if (
            text.includes('beauty') ||
            text.includes('makeup') ||
            text.includes('lipstick') ||
            text.includes('perfume') ||
            text.includes('fragrance') ||
            text.includes('skin-care')
        ) {
            return 'Beauty'
        }


        // JEWELLERY
        if (
            text.includes('jewellery') ||
            text.includes('jewelry') ||
            text.includes('necklace') ||
            text.includes('earring')
        ) {
            return 'Jewellery'
        }


        // BAGS
        if (
            text.includes('bag') ||
            text.includes('handbag') ||
            text.includes('womens-bags')
        ) {
            return 'Bags'
        }


        // FOOTWEAR
        if (
            text.includes('shoe') ||
            text.includes('sandal') ||
            text.includes('footwear')
        ) {
            return 'Footwear'
        }


        // ELECTRONICS
        if (
            text.includes('laptop') ||
            text.includes('mobile') ||
            text.includes('phone') ||
            text.includes('electronic') ||
            text.includes('smartphone') ||
            text.includes('tablet') ||
            text.includes('computer') ||
            text.includes('headphone') ||
            text.includes('mouse') ||
            text.includes('keyboard') ||
            text.includes('playstation') ||
            text.includes('xbox')
        ) {
            return 'Electronics'
        }


        // WATCHES
        if (
            text.includes('watch')
        ) {
            return 'Watches'
        }


        // OTHER
        return 'Popular'
    }


    // =========================================
    // SEARCH + CATEGORY FILTER
    // =========================================

    const filteredProducts = useMemo(() => {

        const search =
            searchTerm
                .toLowerCase()
                .trim()


        return products.filter((product) => {

            const productName =
                (product.name || '')
                    .toLowerCase()

            const description =
                (product.description || '')
                    .toLowerCase()

            const productCategory =
                (product.category || '')
                    .toLowerCase()


            // SEARCH MATCH
            const matchesSearch =
                !search ||
                productName.includes(search) ||
                description.includes(search) ||
                productCategory.includes(search)


            // CATEGORY MATCH
            const matchesCategory =
                !category ||
                category === 'Popular' ||
                getCategory(product) === category


            return (
                matchesSearch &&
                matchesCategory
            )

        })

    }, [products, searchTerm, category])


    // =========================================
    // SEARCH HANDLER
    // =========================================

    const handleSearch = (event) => {

        const value =
            event.target.value


        if (value.trim()) {

            history.push(
                `/?searchTerm=${encodeURIComponent(value)}`
            )

        } else {

            history.push('/')

        }

    }


    // =========================================
    // RENDER
    // =========================================

    return (

        <div className="shopease-home">


            {/* =========================================
                HERO
            ========================================= */}

            {!searchTerm && !category && (

                <section className="hero-section">

                    <div className="hero-overlay">

                        <div className="hero-content">

                            <span className="hero-small-title">
                                WELCOME TO SHOPEASE
                            </span>

                            <h1>
                                Style That Fits You
                            </h1>

                            <p>
                                Discover trending fashion,
                                accessories and everyday essentials
                                at amazing prices.
                            </p>

                            <div className="hero-buttons">

                                <button
                                    className="hero-primary-btn"
                                    onClick={() =>
                                        document
                                            .getElementById('products-section')
                                            ?.scrollIntoView({
                                                behavior: 'smooth'
                                            })
                                    }
                                >
                                    Shop Now
                                </button>


                                <button
                                    className="hero-secondary-btn"
                                    onClick={() =>
                                        document
                                            .getElementById('products-section')
                                            ?.scrollIntoView({
                                                behavior: 'smooth'
                                            })
                                    }
                                >
                                    Explore Products
                                </button>

                            </div>

                        </div>

                    </div>

                </section>

            )}


            {/* =========================================
                BENEFITS
            ========================================= */}

            {!searchTerm && !category && (

                <section className="benefits-section">

                    <div className="benefit-card">
                        <div className="benefit-icon">
                            🚚
                        </div>

                        <div>
                            <h5>Fast Delivery</h5>
                            <p>Delivery across India</p>
                        </div>
                    </div>


                    <div className="benefit-card">
                        <div className="benefit-icon">
                            💵
                        </div>

                        <div>
                            <h5>Cash on Delivery</h5>
                            <p>Pay when your order arrives</p>
                        </div>
                    </div>


                    <div className="benefit-card">
                        <div className="benefit-icon">
                            🔄
                        </div>

                        <div>
                            <h5>Easy Returns</h5>
                            <p>Simple return policy</p>
                        </div>
                    </div>


                    <div className="benefit-card">
                        <div className="benefit-icon">
                            🔒
                        </div>

                        <div>
                            <h5>Secure Payments</h5>
                            <p>100% secure checkout</p>
                        </div>
                    </div>

                </section>

            )}


            {/* =========================================
                SEARCH
            ========================================= */}

            <section className="homepage-search">

                <div className="search-heading">

                    <h2>
                        Find Your Favourite Products
                    </h2>

                    <p>
                        Search from our collection
                    </p>

                </div>


                <div className="modern-search-box">

                    <span>🔍</span>

                    <input
                        type="text"
                        value={searchTerm}
                        onChange={handleSearch}
                        placeholder="Search for products, brands and more"
                    />


                    {searchTerm && (

                        <button
                            onClick={() =>
                                history.push('/')
                            }
                        >
                            ✕
                        </button>

                    )}

                </div>

            </section>


            {/* =========================================
                PRODUCTS
            ========================================= */}

            <section
                id="products-section"
                className="products-section"
            >

                <div className="products-heading">

                    <div>

                        <h2>

                            {searchTerm
                                ? `Search results for "${searchTerm}"`
                                : category
                                    ? `${category} Products`
                                    : 'Popular Products'
                            }

                        </h2>


                        <p>
                            {filteredProducts.length} products found
                        </p>

                    </div>

                </div>


                {/* ERROR */}

                {error && (

                    <Message variant="danger">
                        {error}
                    </Message>

                )}


                {/* LOADING */}

                {loading && (

                    <div className="loading-container">

                        <Spinner animation="border" />

                        <p>
                            Getting products...
                        </p>

                    </div>

                )}


                {/* =========================================
                    PRODUCT LIST
                ========================================= */}

                {!loading && (

                    filteredProducts.length === 0 ? (

                        <div className="empty-products">

                            <div className="empty-icon">
                                🛍️
                            </div>

                            <h3>
                                No products found
                            </h3>

                            <p>
                                Try searching for another
                                product or category.
                            </p>

                            <button
                                onClick={() =>
                                    history.push('/')
                                }
                            >
                                View All Products
                            </button>

                        </div>

                    ) : (

                        <div className="product-grid">

                            {filteredProducts.map((product) => (

                                <Product
                                    key={product.id}
                                    product={product}
                                />

                            ))}

                        </div>

                    )

                )}

            </section>


            {/* =========================================
                SHOPPING BANNER
            ========================================= */}

            {!searchTerm && !category && (

                <section className="shopping-banner">

                    <div>

                        <h2>
                            Shop smarter with ShopEase
                        </h2>

                        <p>
                            Great products. Great prices.
                            Delivered to your doorstep.
                        </p>

                    </div>


                    <button
                        onClick={() =>
                            document
                                .getElementById('products-section')
                                ?.scrollIntoView({
                                    behavior: 'smooth'
                                })
                        }
                    >
                        Start Shopping
                    </button>

                </section>

            )}

        </div>

    )
}

export default ProductsListPage
